+import { describe, expect, test } from "bun:test";
+import { render } from "../src/engine.ts";
+
+describe("render", () => {
+  test("preserves text and escapes interpolated values", () => {
+    expect(render(" A {{value}} B ", { value: "<&>\"'" })).toBe(" A &lt;&amp;&gt;&quot;&#39; B ");
+    expect(render("{{{value}}}", { value: "<b>ok</b>" })).toBe("<b>ok</b>");
+  });
+
+  test("renders missing values and comments as empty strings", () => {
+    expect(render("x{{missing}}y{{! ignored }}z", {})).toBe("xyz");
+  });
+
+  test("supports nested conditional blocks and specified falsey values", () => {
+    const template = "{{#if enabled}}yes {{#if name}}{{name}}{{else}}anonymous{{/if}}{{else}}no{{/if}}";
+    expect(render(template, { enabled: true, name: "Ada" })).toBe("yes Ada");
+    expect(render(template, { enabled: true, name: "" })).toBe("yes anonymous");
+    expect(render("{{#if value}}yes{{else}}no{{/if}}", { value: [] })).toBe("no");
+  });
+
+  test("iterates arrays with item scope, index, root fallback, and nesting", () => {
+    const template = "{{#each groups}}[{{title}}:{{#each values}}{{@index}}={{this}}/{{../bad}}{{/each}}]{{/each}}";
+    // Named values from an item resolve before root values; missing values remain empty.
+    expect(render(template, { groups: [{ title: "A", values: ["x", "y"] }] })).toBe("[A:0=x/1=y/]");
+    expect(render("{{#each values}}{{@index}} {{this}} {{label}};{{else}}empty{{/each}}", { values: ["a", "b"], label: "root" })).toBe("0 a root;1 b root;");
+    expect(render("{{#each values}}x{{else}}empty{{/each}}", { values: [] })).toBe("empty");
+  });
+
+  test("rejects structural errors with locations", () => {
+    for (const template of ["{{else}}", "{{#if ok}}{{else}}{{else}}{{/if}}", "{{#if ok}}{{/each}}", "{{#each xs}}", "{{#wat ok}}{{/wat}}"] ) {
+      expect(() => render(template, {})).toThrow(/line 1, column/);
+    }
+  });
+
+  test("rejects non-scalar interpolation values", () => {
+    expect(() => render("{{value}}", { value: {} })).toThrow("Cannot render object or function");
+    expect(() => render("{{value}}", { value: () => "x" })).toThrow("Cannot render object or function");
+  });
+});
