+type Position = { line: number; column: number };
+
+type TextNode = { type: "text"; value: string };
+type ValueNode = { type: "value"; path: string; escaped: boolean; position: Position };
+type BlockNode = {
+  type: "block";
+  kind: "if" | "each";
+  path: string;
+  body: Node[];
+  alternate: Node[] | null;
+  position: Position;
+};
+type Node = TextNode | ValueNode | BlockNode;
+
+type Frame = { node: BlockNode; parent: Node[]; inElse: boolean };
+type Context = { root: unknown; value: unknown; index?: number };
+
+function positionAt(input: string, offset: number): Position {
+  let line = 1;
+  let column = 1;
+  for (let i = 0; i < offset; i += 1) {
+    if (input[i] === "\n") {
+      line += 1;
+      column = 1;
+    } else {
+      column += 1;
+    }
+  }
+  return { line, column };
+}
+
+function error(message: string, position: Position): Error {
+  return new Error(`${message} at line ${position.line}, column ${position.column}`);
+}
+
+function validPath(path: string): boolean {
+  return path === "this" || path === "@index" || /^[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*$/.test(path);
+}
+
+function parse(template: string): Node[] {
+  const root: Node[] = [];
+  let current = root;
+  const frames: Frame[] = [];
+  let cursor = 0;
+
+  while (cursor < template.length) {
+    const start = template.indexOf("{{", cursor);
+    if (start === -1) {
+      if (cursor < template.length) current.push({ type: "text", value: template.slice(cursor) });
+      break;
+    }
+    if (start > cursor) current.push({ type: "text", value: template.slice(cursor, start) });
+
+    const triple = template.startsWith("{{{", start);
+    const close = triple ? "}}}" : "}}";
+    const contentStart = start + (triple ? 3 : 2);
+    const end = template.indexOf(close, contentStart);
+    const position = positionAt(template, start);
+    if (end === -1) throw error("Unclosed tag", position);
+
+    const content = template.slice(contentStart, end).trim();
+    cursor = end + close.length;
+    if (content.startsWith("!")) continue;
+
+    if (!triple && content.startsWith("#")) {
+      const match = /^#(if|each)\s+(.+)$/.exec(content);
+      if (!match || !validPath(match[2].trim())) throw error(`Unknown or invalid block '${content}'`, position);
+      const node: BlockNode = {
+        type: "block",
+        kind: match[1] as "if" | "each",
+        path: match[2].trim(),
+        body: [],
+        alternate: null,
+        position,
+      };
+      current.push(node);
+      frames.push({ node, parent: current, inElse: false });
+      current = node.body;
+      continue;
+    }
+
+    if (!triple && content === "else") {
+      const frame = frames.at(-1);
+      if (!frame) throw error("'else' outside a block", position);
+      if (frame.inElse) throw error("Duplicate 'else'", position);
+      frame.inElse = true;
+      frame.node.alternate = [];
+      current = frame.node.alternate;
+      continue;
+    }
+
+    if (!triple && content.startsWith("/")) {
+      const name = content.slice(1).trim();
+      const frame = frames.at(-1);
+      if (name !== "if" && name !== "each") throw error(`Unknown block close '${content}'`, position);
+      if (!frame) throw error(`Unexpected closing tag '${content}'`, position);
+      if (frame.node.kind !== name) {
+        throw error(`Mismatched closing tag '${content}', expected '/${frame.node.kind}'`, position);
+      }
+      frames.pop();
+      current = frame.parent;
+      continue;
+    }
+
+    if (!validPath(content)) throw error(`Invalid interpolation '${content}'`, position);
+    current.push({ type: "value", path: content, escaped: !triple, position });
+  }
+
+  const unclosed = frames.at(-1);
+  if (unclosed) throw error(`Unclosed block '${unclosed.node.kind}'`, unclosed.node.position);
+  return root;
+}
+
+function getPath(source: unknown, parts: string[]): unknown {
+  let value = source;
+  for (const part of parts) {
+    if (value === null || value === undefined || (typeof value !== "object" && typeof value !== "function")) return undefined;
+    if (!Object.prototype.hasOwnProperty.call(value, part)) return undefined;
+    value = (value as Record<string, unknown>)[part];
+  }
+  return value;
+}
+
+function resolve(path: string, context: Context): unknown {
+  if (path === "this") return context.value;
+  if (path === "@index") return context.index;
+  const parts = path.split(".");
+  const scoped = getPath(context.value, parts);
+  return scoped === undefined ? getPath(context.root, parts) : scoped;
+}
+
+function isTruthy(value: unknown): boolean {
+  return !(
+    value === false ||
+    value === null ||
+    value === undefined ||
+    value === 0 ||
+    value === "" ||
+    (Array.isArray(value) && value.length === 0)
+  );
+}
+
+function stringify(value: unknown, position: Position): string {
+  if (value === null || value === undefined) return "";
+  if (typeof value === "object" || typeof value === "function") {
+    throw error("Cannot render object or function value as text", position);
+  }
+  return String(value);
+}
+
+function escapeHtml(value: string): string {
+  return value.replace(/[&<>"']/g, (character) => ({
+    "&": "&amp;",
+    "<": "&lt;",
+    ">": "&gt;",
+    '"': "&quot;",
+    "'": "&#39;",
+  })[character]!);
+}
+
+function renderNodes(nodes: Node[], context: Context): string {
+  let output = "";
+  for (const node of nodes) {
+    if (node.type === "text") {
+      output += node.value;
+    } else if (node.type === "value") {
+      const value = stringify(resolve(node.path, context), node.position);
+      output += node.escaped ? escapeHtml(value) : value;
+    } else {
+      const value = resolve(node.path, context);
+      if (node.kind === "if") {
+        output += renderNodes(isTruthy(value) ? node.body : (node.alternate ?? []), context);
+      } else if (Array.isArray(value) && value.length > 0) {
+        for (let index = 0; index < value.length; index += 1) {
+          output += renderNodes(node.body, { root: context.root, value: value[index], index });
+        }
+      } else {
+        output += renderNodes(node.alternate ?? [], context);
+      }
+    }
+  }
+  return output;
+}
+
+/** Renders a Mini Template string with values from the supplied data object. */
+export function render(template: string, data: unknown): string {
+  return renderNodes(parse(template), { root: data, value: data });
+}

